\textbf{\textcolor{red}{FOC for maximization --- HIGH SCHOOL (free max) vs UNIVERSITY (KKT, constrained).}}

\begin{tabular}{p{17.2cm}|p{17.2cm}}
\textbf{\textcolor{red}{HS version: free max (F)}} & \textbf{\textcolor{red}{Uni version: constrained max (P), KKT}} \\
\textit{Problem (F):} $\max_{x \in \mathbb{R}^N} f(x)$. & \textit{Problem (P):} $\max_x f(x)$ \;s.t.\; $g_k(x) \geq 0,\;k=1,\ldots,K$.  \\
\hline
\textbf{\textcolor{red}{Necessity ($\Rightarrow$).}} \underline{If} $x^*$ solves (F) (or is a local max), \textcolor{blue}{$f$ differentiable}, \underline{then}
\[ \boxed{\;\nabla f(x^*) = 0.\;} \]
\emph{\textcolor{orange}{$\nabla f(x^*) = 0$ is a necessary condition for a max.}}
&
\textbf{\textcolor{red}{Necessity ($\Rightarrow$).}} \underline{If} $x^*$ is feasible ($g_k(x^*) \geq 0\;\forall k$) and a local max, \textcolor{blue}{$f, g_k$ differentiable} and \textcolor{blue}{CQ} holds at $x^*$, \underline{then} \textbf{KKT conditions hold}: $\exists$ nonnegative scalars $\lambda^* = [\lambda_1^*, \ldots, \lambda_K^*]$ such that
\[ \tfrac{\partial \mathcal{L}(x^*, \lambda^*)}{\partial x_n} = \tfrac{\partial f(x^*)}{\partial x_n} + \sum_k \lambda_k^*\, \tfrac{\partial g_k(x^*)}{\partial x_n} = 0, \]
plus \textbf{CS}: $\lambda_k^*\, g_k(x^*) = 0\;\forall k$, that is $\forall k$ if $g_k(x^*) > 0 \rightarrow  \lambda_k^* = 0$.
\emph{\textcolor{orange}{KKT are necessary conditions for a max.}}
\\
\hline
\textbf{\textcolor{red}{Sufficiency ($\Leftarrow$).}} \underline{If} \textcolor{blue}{$f$ differentiable and concave} \underline{then} $\nabla f(x^*) = 0$ \emph{iff} $x^*$ solves (F).
\emph{\textcolor{orange}{Under concavity, FOC is also sufficient.}}
&
\textbf{\textcolor{red}{Sufficiency ($\Leftarrow$).}} \underline{If} \textcolor{blue}{$f, g_k$ concave and differentiable} and $\exists\,\underline{x}$ such that $g_k(\underline{x}) > 0\;\forall k$ (\textcolor{blue}{Slater}), \underline{then} a feasible $x^*$ solves (P) \emph{iff} KKT holds.
\emph{\textcolor{orange}{Under concavity + Slater, KKT is necessary \emph{and} sufficient (iff).}}
\\
\hline
\textbf{\textcolor{red}{Notes.}}
$\bullet$ Without \textcolor{blue}{concavity}, $\nabla f(x^*) = 0$ alone $\Rightarrow$ $x^*$ is only a \emph{stationary point} (min, saddle, or max).
$\bullet$ Nonneg-constrained variant ($x_n \geq 0$), \emph{necessity only}: $\;\tfrac{\partial f(x^*)}{\partial x_n} \leq 0,\;\; = 0\text{ if } x_n^* > 0.$

{{img:0|w=800}}
&
\textbf{\textcolor{red}{Notes.}}
$\bullet$ Without \textcolor{blue}{concavity} + Slater, KKT only implies $x^*$ is \emph{stationary} (could be local max, min, or saddle).
\\
\end{tabular}

\textbf{\textcolor{red}{APPLICATIONS --- using KKT in practice.}}

\textbf{\textcolor{red}{Key implication of the sufficiency side.}}

\underline{If} the \emph{sufficient}-side assumptions hold ---  \textcolor{blue}{$f, g_k$ concave and differentiable} and \textcolor{blue}{Slater} ($\exists\,\underline{x}$ such that $g_k(\underline{x}) > 0\;\forall k$) --- \underline{then}:
\[ \boxed{\;x^* \text{ satisfies KKT} \;\;\Longrightarrow\;\; x^* \text{ is a feasible (global) maximum of (P).}\;} \]

\textbf{\textcolor{red}{Practical recipe.}} For problem (P): $\max_{x \in \mathbb{R}^N} f(x)$ s.t.\ $g(x) \geq 0$ (i.e.\ $g_k(x) \geq 0,\;k=1,\ldots,K$):
\begin{enumerate}
\item Write all constraints in \textcolor{orange}{canonical form} $g(x) \geq 0$.
\item Write the Lagrangian: $\mathcal{L}(x, \lambda) = f(x) + \lambda \cdot g(x)$.
\item Recall $\lambda^* \geq 0$.
\item \textbf{FOCs --- one per component} $x_n$, $n = 1, \ldots, N$:\[ \tfrac{\partial \mathcal{L}(x^*, \lambda^*)}{\partial x_n} \;=\; \tfrac{\partial f(x^*)}{\partial x_n} + \sum_{k=1}^{K} \lambda_k^*\, \tfrac{\partial g_k(x^*)}{\partial x_n} \;=\; 0. \]\emph{$N$ equations, one for each decision variable $x_n$.}
\item Verify feasibility: $g(x^*) \geq 0$.
\item Complementary slackness: $\lambda_k^*\, g_k(x^*) = 0\;\forall k$.
\end{enumerate}

\textbf{\textcolor{red}{How to read the output.}}
$\bullet$ If \textcolor{blue}{concavity + Slater hold} $\Rightarrow$ steps 1--6 give the \emph{full} characterization of the optimum (\textcolor{orange}{necessary \emph{and} sufficient}).
$\bullet$ If only \textcolor{blue}{differentiability + CQ} hold (no concavity) $\Rightarrow$ steps 1--6 are only \textcolor{orange}{necessary}; the candidate $x^*$ may be a local max, min, or saddle. Must compare candidates or use second-order conditions.

\textbf{\textcolor{red}{2.1 --- CONSUMER PROBLEM: setup, value $v(p,w)$, demand $x^*(p,w)$, existence \& uniqueness.}}

\emph{Primitives.} Utility $U: \mathbb{R}_+^N \to \mathbb{R}$ continuous, concave. Bundle $x = (x_1,\ldots,x_N)$ (may include leisure). Prices $p \in \mathbb{R}_{++}^N$, wealth $w > 0$.

\begin{keydef}
\textbf{Budget set.} $\;B(p,w) := \{x \in \mathbb{R}_+^N : \sum_n p_n x_n \leq w\}$.

Key properties: compact (since $0 \leq x_n \leq w/p_n$), convex, and \textcolor{orange}{scale-invariant}: $B(\alpha p, \alpha w) = B(p,w)$ for all $\alpha > 0$.
\end{keydef}

\begin{keydef}
\textbf{Consumer problem.} $\;\; v(p,w) := \max_{x \in B(p,w)} U(x). \tag{2.1}$

$v(\cdot)$ is the \textit{indirect utility}; the maximizer $x^*(p,w)$ is the (uncompensated / Walrasian / Marshallian) \textit{demand function}.
\end{keydef}

\textbf{\textcolor{red}{Three preliminary facts (read \emph{before} solving).}}
$\bullet$ \textbf{Existence:} $B$ compact + $U$ continuous $\Rightarrow$ Bolzano-Weierstrass: $x^*(p,w)$ exists for all $(p,w) > 0$.
$\bullet$ \textbf{Uniqueness:} $B$ convex + $U$ \emph{strictly} concave $\Rightarrow$ $x^*(p,w)$ unique (hence a function). Maximum theorem $\Rightarrow$ $x^*(\cdot)$ continuous.
$\bullet$ \textbf{Homogeneity degree 0:} $B$ scale-invariant $\Rightarrow$ $x^*(\alpha p, \alpha w) = x^*(p, w)$ for all $\alpha > 0$.

\emph{Pointer to next:} Apply KKT (Ch.1, Theorem 2) to derive the FOCs $\to$ note 2.2.

\textbf{\textcolor{red}{2.4 --- DUALITY: expenditure minimization, Hicksian demand, Slutsky equation.}}

\textbf{\textcolor{red}{Dual problem (expenditure minimization).}}
\[ e(p, \underline u) := \min_x \sum_n p_n x_n \quad \text{s.t.}\quad U(x) \geq \underline u. \]
$e(p, \underline u)$ = \textit{expenditure function}; minimizer $x^C(p, \underline u)$ = \textit{Hicksian / compensated demand}.

\textbf{\textcolor{red}{Primal-dual identities.}}
\[ x_i^C(p, \underline u) = x_i^*(p,\, e(p, \underline u)), \qquad x_i^*(p, w) = x_i^C(p,\, v(p, w)). \]
\emph{Reading.} Fixing prices: the Hicksian for $\underline u$ equals Marshallian when wealth is just enough to reach $\underline u$.

\textbf{\textcolor{red}{Slutsky equation.}} Differentiate the first identity in $p_i$ (envelope: $\partial e/\partial p_i = x_i^C$):
\[ \boxed{\;\underbrace{\tfrac{\partial x_i^*(p,w)}{\partial p_i}}_{\text{total (uncomp.)}} \;=\; \underbrace{\tfrac{\partial x_i^C(p, \underline u)}{\partial p_i}}_{\text{substitution effect}} \;-\; \underbrace{\tfrac{\partial x_i^*(p,w)}{\partial w}\, x_i^*(p,w)}_{\text{income effect}}.\;} \tag{2.2} \]
\emph{Intuition.} A price rise: (i) substitution — swap toward cheaper goods at the \emph{same} utility level; (ii) income — you became effectively poorer ($\Delta w \approx -x_i^* \cdot \Delta p_i$).

\textbf{\textcolor{red}{2.5 --- DEMAND ELASTICITY (log-derivative).}}

\begin{keydef}
\textbf{(Uncompensated) elasticity:} $\;\;\epsilon_{n, p_k} := \dfrac{\partial \ln x_n^*(p,w)}{\partial \ln p_k} = \dfrac{\partial x_n^*}{\partial p_k}\, \dfrac{p_k}{x_n^*}.$
\end{keydef}

\emph{Reading.} $\epsilon_{n, p_k}$ = percent change in demand for good $n$ from a 1\% change in price $p_k$. Unit-free $\Rightarrow$ comparable across goods/markets.

\emph{Sign conventions (concave $U$, normal goods).}
$\bullet$ Own price: $\epsilon_{n, p_n} < 0$ (typical) — \emph{Giffen} goods are the exception.
$\bullet$ Cross price: $\epsilon_{n, p_k} > 0$ means substitutes; $< 0$ means complements.
$\bullet$ Income elasticity $\epsilon_{n,w} := \partial \ln x_n^*/\partial \ln w$: normal ($>0$), inferior ($<0$), luxury ($>1$), necessity ($\in (0,1)$).

\textbf{\textcolor{red}{2.6 --- INDIRECT UTILITY $v(p,w)$ \& ROY'S IDENTITY.}}

\emph{Defn.} $v(p, w) = U(x^*(p, w))$. Inherited properties:
$\bullet$ Homogeneous of degree 0: $v(\alpha p, \alpha w) = v(p, w)$.
$\bullet$ Strictly increasing in $w$ (if $U$ strictly increasing in some good): $\partial v/\partial w > 0$.
$\bullet$ Non-increasing in each $p_n$: $\partial v/\partial p_n \leq 0$.

\begin{keydef}
\textbf{Proposition (Roy's identity).} If $x^*$ satisfies Walras's law and $v$ is differentiable:
\[ x_n^*(p, w) = -\dfrac{\partial v(p, w)/\partial p_n}{\partial v(p, w)/\partial w}, \qquad n = 1, \ldots, N. \]
\end{keydef}

\textbf{\textcolor{red}{Proof (via envelope theorem on the Lagrangian).}}
\begin{proof}
CS gives $v(p,w) = U(x^*) + \lambda^*[w - \sum p_n x_n^*]$ (the bracket is $0$ when budget binds). Envelope:
\[ \tfrac{\partial v}{\partial w} = \lambda^*(p,w), \qquad \tfrac{\partial v}{\partial p_n} = -\lambda^*(p,w)\, x_n^*(p,w). \]
Take the ratio $\Rightarrow$ multiplier cancels $\Rightarrow$ Roy. $\square$
\end{proof}

\emph{Heuristic envelope check (for $\partial v/\partial w$):} brute-force chain rule gives
\[ \tfrac{\partial v}{\partial w} = \sum_n\underbrace{\bigl[\tfrac{\partial U}{\partial x_n} - \lambda^* p_n\bigr]}_{=0\text{ by FOC}}\tfrac{\partial x_n^*}{\partial w} + \lambda^*[\underbrace{w - \sum p_n x_n^*}_{=0\text{ Walras}}]_\text{deriv}\cdot \tfrac{\partial \lambda^*}{\partial w} + \lambda^* = \lambda^*. \]
\textcolor{orange}{Economic reading of $\lambda^*$: marginal value of wealth.}

\textbf{\textcolor{red}{2.8 --- HOMOTHETIC PREFERENCES: demand linear in wealth.}}

\begin{keydef}
\textbf{Homothetic.} $U(x) = g(h(x))$ with $g$ strictly increasing and $h$ homogeneous of degree 1 ($h(\alpha x) = \alpha h(x)$ for all $\alpha > 0$).
\end{keydef}

\textbf{\textcolor{red}{Implication: multiplicative-in-wealth structure.}}
\[ v(p, w) = v(p)\, w, \qquad x_i^*(p, w) = x_i(p)\, w. \]
\emph{Intuition.} Scaling wealth by $\alpha$ scales the budget set by $\alpha$; homogeneity of $h$ scales the level sets uniformly $\Rightarrow$ optimal bundle scales by $\alpha$.

\textcolor{orange}{Why useful.} Aggregation across heterogeneous agents and over time is trivial: total demand = price-only function $\times$ aggregate wealth — standard tool in macro.

\textbf{\textcolor{red}{Parametric example.}} $U(x_1, x_2) = \sqrt{x_1}\sqrt{x_2}$. Homothetic (it is itself homogeneous of degree 1). Also $\hat U(x) = \ln x_1 + \ln x_2$ is homothetic (monotone transformation, $g = \ln \circ \text{(itself)}^2$). FOCs give Cobb-Douglas-style $x_i^*(p,w) = w/(2 p_i)$.

\textbf{\textcolor{red}{3.1 --- EXCHANGE ECONOMY \& EDGEWORTH BOX (setup, feasibility, budget line).}}

\emph{Primitives.} $I$ consumers, $N$ goods. Each $i$: utility $U^i: \mathbb{R}^N \to \mathbb{R}$, endowment $\omega^i = (\omega^i_1, \ldots, \omega^i_N) \geq 0$. No production. Allocation $x = (x^1, \ldots, x^I)$.

\begin{keydef}
\textbf{Feasibility.} $\;\mathcal{F} = \{x : \sum_i x^i_n \leq \sum_i \omega^i_n\;\forall n;\; x^i_n \geq 0\}.$ \textbf{Non-wasteful} $=$ equality.
\end{keydef}

\textbf{\textcolor{red}{Edgeworth box ($I=N=2$).}} Rectangle with side lengths $\omega_n := \omega^1_n + \omega^2_n$. Agent 1 origin at SW vertex; Agent 2 origin at NE vertex (axes flipped). Point in box $\Leftrightarrow$ non-wasteful allocation. Endowment $\omega$ is a single point (Agent 1's $\omega^1$ = Agent 2's $\omega^2$ by construction).

\emph{Budget constraint at prices $(p_\ell, p_h)$.}
\[ p_h(\omega^i_h - x^i_h) + p_\ell(\omega^i_\ell - x^i_\ell) \geq 0. \]
The \textcolor{orange}{budget line} passes through $\omega$ with slope $-p_\ell/p_h$ in the box. Endowment trivially satisfies it with equality.

\textbf{\textcolor{red}{3.2a --- COMPETITIVE (WALRASIAN) EQUILIBRIUM: definition + existence (sketch).}}

\begin{keydef}
\textbf{Definition 9 (CE).} A pair $(\hat p, \hat x)$ is a competitive equilibrium if:

\textbf{(i) Individual optimality.} Each $\hat x^i$ solves
\[ \max_{x^i \geq 0} U^i(x^i) \;\;\text{s.t.}\;\; \hat p \cdot (\omega^i - x^i) \geq 0. \]
\textbf{(ii) Market clearing.} $\sum_i \hat x^i_n = \sum_i \omega^i_n$ for all $n$.
\end{keydef}

\emph{Edgeworth reading.} At CE the two indifference curves are tangent to a \emph{common} budget line through $\omega$; tangency point lies in the box (market clearing).

\begin{keydef}
\textbf{Theorem 5 (Existence of CE).} If each $U^i$ is continuous, strictly increasing, strictly concave, and $\omega_n > 0$ for all $n$, then a CE $(\hat p, \hat x)$ with $\hat p > 0$ exists.
\end{keydef}

\textbf{\textcolor{red}{Sketch (N=2, intermediate value theorem on excess demand).}}
\begin{proof}
(1) WLOG $\hat p > 0$ (strict monotonicity). (2) By Walras's law (next note), focus on one market — say good $h$; clearing there $\Rightarrow$ clearing in $\ell$. (3) Fix $\bar p_\ell > 0$. Strict concavity + continuity + maximum theorem $\Rightarrow$ $z_h(p) := \sum_i x^i_h(p) - \omega_h$ is continuous in $p_h$. (4) $p_h \to 0^+$: at least one $i$ demands $\infty$ of $h$ (monotonicity), so $z_h > 0$. $p_h \to \infty$: $x^i_h \to 0\;\forall i$, so $z_h \to -\omega_h < 0$. (5) MVT $\Rightarrow$ $\exists\, p_h^* > 0$ with $z_h(\bar p_\ell, p_h^*) = 0$. $\square$
\end{proof}

\textbf{\textcolor{red}{3.2b --- WALRAS'S LAW + uniqueness via Gross Substitutes (GS).}}

\textbf{\textcolor{red}{Walras's Law.}} Strict monotonicity $\Rightarrow$ each agent's budget binds: $\sum_n p_n x^i_n(p) = \sum_n p_n \omega^i_n$. Aggregate:
\[ \boxed{\;\sum_n p_n \bigl[\textstyle\sum_i (x^i_n(p) - \omega^i_n)\bigr] = 0 \quad \forall p > 0.\;} \]

\emph{Power.} If markets clear in $N-1$ goods, the last one clears \emph{automatically} (the dot product of price vector with excess demand is zero, and $N-1$ of the excess demands are zero, so the last term must also be zero given $p_N > 0$).

\textbf{\textcolor{red}{Multiplicity \& numeraire.}} If $(\hat p, \hat x)$ is a CE then so is $(\alpha \hat p, \hat x)$ for any $\alpha > 0$ (budget set unchanged). To eliminate this trivial multiplicity, normalize one price to 1 (numeraire). Only \emph{relative} prices matter.

\begin{keydef}
\textbf{Definition (GS, gross substitutes).} $z(\cdot)$ has GS if $p'_n > p_n$ and $p'_k = p_k\;\forall k\neq n$ implies $z_k(p') > z_k(p)$ for all $k \neq n$ (raising one price raises demand for \emph{every other} good).
\end{keydef}

\begin{keydef}
\textbf{Proposition (Uniqueness).} GS aggregate excess demand $\Rightarrow$ at most one CE (up to scaling).
\end{keydef}

\begin{proof}
Suppose $z_h(p) = z_h(p') = 0$ with $p' \neq \alpha p$. Homogeneity degree 0 of $z$: scale $p$ by $\hat\alpha > 0$ so $\hat\alpha p_h = p'_h$, with $z_h$ unchanged. WLOG $\hat\alpha p_\ell > p'_\ell$. GS (lowering $p_\ell$ from $\hat\alpha p_\ell$ to $p'_\ell$): $z_h(p') > z_h(\hat\alpha p) = 0$. Contradiction with $z_h(p') = 0$. $\square$
\end{proof}

\textbf{\textcolor{red}{3.3 --- PARETO OPTIMALITY \& Contract Curve.}}

\begin{keydef}
\textbf{Definition 10 (Pareto Optimal).} $x \in \mathcal{F}$ is PO iff $\not\exists\,y \in \mathcal{F}$ with $U^i(y^i) \geq U^i(x^i)\;\forall i$ and strict for some $i$.
\textbf{Pareto set:} $PS = \{x \in \mathcal{F} : x \text{ is PO}\}$.
\end{keydef}

\emph{Why PO is desirable.} Avoids interpersonal utility comparisons; if $y$ Pareto-dominates $x$, all agents unanimously prefer the move $x \to y$.

\textbf{\textcolor{red}{Interior characterization (concave \& differentiable, $I=N=2$).}}
\[ x \in PS \cap \text{interior} \quad\Longleftrightarrow\quad \text{indifference curves are tangent at } x. \]
\emph{Why.} If not tangent, MRS's differ between agents, so there's a small trade improving both. Caution: at \emph{corners} of the box, PO can fail tangency — must check edges separately.

\begin{keydef}
\textbf{Definition 11 (Contract Curve, given $\omega$).} $\;CC = \{x \in PS : U^i(x^i) \geq U^i(\omega^i)\;\forall i\}$.
\end{keydef}

\emph{Reading.} CC = PO allocations that are weakly preferred to autarchy by everyone. CE allocation $\hat x$ belongs to $CC$ (foreshadowing 1st Welfare Thm).

\textbf{\textcolor{red}{3.4 --- LINEAR SOCIAL WELFARE $\Leftrightarrow$ PARETO (Prop 6): the key bridge.}}

\begin{keydef}
\textbf{Definition 12 (Utility Possibility Set \& Frontier).}
\[ \mathcal{U} = \{(u^1, u^2) : \exists x \in \mathcal{F},\, (U^1(x^1), U^2(x^2)) \geq (u^1, u^2)\}. \]
$UPF$ = NE frontier (Pareto-undominated points in $\mathcal{U}$). Concave $U^i$'s $\Rightarrow$ $\mathcal{U}$ convex.
\end{keydef}

\textbf{\textcolor{red}{Linear social welfare problem (Prob 3.3).}}
\[ \max_{x \in \mathcal{F}} \;\;\lambda U^1(x^1) + (1-\lambda)\, U^2(x^2), \quad \lambda \in [0,1]. \]

\begin{keydef}
\textbf{Proposition 6.}
\textbf{(i)} If $\bar x$ solves (3.3) with $\lambda \in (0,1)$, then $\bar x$ is PO.
\textbf{(ii)} If each $U^i$ is concave \& increasing and $\bar x$ is PO, then $\exists\,\lambda \in [0,1]$ such that $\bar x$ solves (3.3).
\end{keydef}

\textbf{\textcolor{red}{Proof.}}
\begin{proof}
\textbf{(i)} Contrapositive. If $\bar x$ not PO, $\exists\,\hat x$ with $U^i(\hat x) \geq U^i(\bar x)\,\forall i$ and strict for some $i$. Then for $\lambda \in (0,1)$, the social welfare at $\hat x$ exceeds that at $\bar x$. Contradiction.

\textbf{(ii)} Use \textcolor{orange}{separation theorem} in utility space (recall Ch.1 separation $\to$ KT 1(ii)). Translate $\mathcal{U}$ so $\bar u := (U^1(\bar x), U^2(\bar x))$ sits at origin: $\mathcal{U}(\bar x)$. $\bar x$ PO $\Rightarrow$ $\bar u$ is boundary of $\mathcal{U}$ $\Rightarrow$ $\mathcal{U}(\bar x) \cap \mathbb{R}_+^2 = \{0\}$. Convex $\mathcal{U}$ + separation: $\exists\,(\alpha^1, \alpha^2) \neq 0$ with
\[ \alpha^1(u^1 - \bar u^1) + \alpha^2(u^2 - \bar u^2) \leq 0 \quad \forall u \in \mathcal{U}. \]
$\alpha^i \geq 0$ (else line enters positive orthant); $\alpha^1 + \alpha^2 > 0$ (since nonzero). Set $\lambda = \alpha^1/(\alpha^1 + \alpha^2) \in [0,1]$, $1-\lambda = \alpha^2/(\alpha^1 + \alpha^2)$. $\square$
\end{proof}

\emph{Tight analogy with KT 1(ii):} Prob (3.2) (max $U^2$ s.t.\ $U^1 \geq u_1$) gives PO via a constrained max; the multiplier on the $U^1$ constraint is essentially $\lambda/(1-\lambda)$.

\textbf{\textcolor{red}{3.5 --- FIRST WELFARE THEOREM: every CE is Pareto efficient.}}

\begin{keydef}
\textbf{Theorem 7 (FWT).} If each $U^i$ is strictly increasing, then any CE allocation $\hat x$ is PO, and $U^i(\hat x^i) \geq U^i(\omega^i)$ for all $i$ (trade weakly preferred to autarchy).
\end{keydef}

\emph{Remarkable.} Far fewer assumptions than existence! No concavity needed for FWT.

\textbf{\textcolor{red}{Lemma 1 (the workhorse).}} Let $(\hat p, \hat x)$ be a CE, each $U^i$ strictly increasing. Then for all $i$, $\forall x^i$:
\textbf{(1)} $U^i(x^i) > U^i(\hat x^i) \Rightarrow \hat p \cdot (\omega^i - x^i) < 0$ \;(strictly more expensive);
\textbf{(2)} $U^i(x^i) \geq U^i(\hat x^i) \Rightarrow \hat p \cdot (\omega^i - x^i) \leq 0$ \;(at least as expensive).

\begin{proof}[Proof of Lemma]
\textbf{(1)} If $U^i(x^i) > U^i(\hat x^i)$ \emph{and} $\hat p \cdot (\omega^i - x^i) \geq 0$, then $x^i$ is feasible and better $\Rightarrow$ $\hat x^i$ wasn't optimal. Contradiction.
\textbf{(2)} If $U^i(x^i) \geq U^i(\hat x^i)$ and $\hat p \cdot (\omega^i - x^i) > 0$: strict monotonicity lets us perturb to $\tilde x^i$ slightly with $U^i(\tilde x^i) > U^i(\hat x^i)$, still feasible. Same contradiction. $\square$
\end{proof}

\textbf{\textcolor{red}{Proof of FWT.}}
\begin{proof}
Suppose $y$ Pareto-dominates $\hat x$. Lemma 1: $\sum_n \hat p_n (\omega^i_n - y^i_n) \leq 0\;\forall i$, strict for the agent strictly improved. Sum over $i$:
\[ \sum_i \sum_n \hat p_n (\omega^i_n - y^i_n) < 0 \;\;\Longleftrightarrow\;\; \sum_n \hat p_n \bigl[\textstyle\sum_i (\omega^i_n - y^i_n)\bigr] < 0. \]
But feasibility of $y$ means $\sum_i y^i_n \leq \sum_i \omega^i_n$, i.e.\ $\sum_i (\omega^i_n - y^i_n) \geq 0$. With $\hat p > 0$, sum $\geq 0$ — contradicts $< 0$. $\square$
\end{proof}

\textcolor{orange}{Economic intuition.} A Pareto-improving allocation must be \emph{more expensive in aggregate} (Lemma 1). But aggregate expenditure = aggregate endowment value (Walras). Contradiction.

\emph{Caveats (when FWT fails).} Non-price-taking (market power); externalities/public goods; market incompleteness; non-rational agents.

\textbf{\textcolor{red}{3.6 --- SECOND WELFARE THEOREM: every PO is a CE \emph{with transfers}.}}

\emph{CE with transfers.} $\bar x$ is supportable as a CE-with-transfers if $\exists\,\hat p,\, (T^1, \ldots, T^I)$ with $\sum_i T^i = 0$ such that each $\bar x^i$ maxes $U^i$ s.t.\ $\hat p \cdot (\omega^i - x^i) + T^i \geq 0$ \emph{and} markets clear.

\begin{keydef}
\textbf{Theorem 8 (SWT).} If each $U^i$ is continuous, strictly concave, strictly increasing, and $\omega_n > 0\,\forall n$, then every PO $\bar x$ is supportable as a CE with transfers.
\end{keydef}

\textbf{\textcolor{red}{Proof (2 steps).}}
\begin{proof}
\textbf{Step 1.} Consider the economy where $\bar x$ \emph{is} the endowment. By Existence (Thm 5), it has a CE $(\hat p, \hat x)$. Since $\bar x^i$ is feasible for agent $i$'s problem there: $U^i(\hat x^i) \geq U^i(\bar x^i)$. Market clearing $\Rightarrow$ $\sum_i \hat x^i_n = \sum_i \bar x^i_n$, so $\hat x$ is feasible in the original economy. PO of $\bar x$ forbids strict improvement, so $U^i(\hat x^i) = U^i(\bar x^i)$ for all $i$.

Strict concavity + convexity of $\mathcal{F}$: if $\hat x \neq \bar x$, then $x_\alpha = \alpha \hat x + (1-\alpha) \bar x \in \mathcal{F}$ and $U^i(x^i_\alpha) > U^i(\bar x^i)\,\forall i$, contradicting PO of $\bar x$. Hence $\hat x = \bar x$.

\textbf{Step 2.} Build the transfer that re-anchors the consumer problem from $\omega^i$ to $\bar x^i$: set $T^i = \hat p \cdot (\bar x^i - \omega^i)$ for each $i$. Then $\sum_i T^i = 0$ (since $\sum_i \bar x^i = \sum_i \omega^i$) and the new budget set equals the one with endowment $\bar x^i$ that we used in Step 1. $\square$
\end{proof}

\emph{Failure modes.} Lack of monotonicity (existence fails); lack of concavity (no separating price supporting $Z$ as CE — see Edgeworth example $Z$ with non-convex preferences).

\textbf{\textcolor{red}{4.5 --- PUBLIC GOODS: definition + CE under-provision (Samuelson vs free-riding).}}

\begin{keydef}
\textbf{Pure public good.} \textcolor{orange}{Non-rivalrous} (one's consumption doesn't reduce others') \emph{and} \textcolor{orange}{non-excludable}. Cf.\ club goods (non-rival, excludable, e.g.\ bridges); common-pool resources (rival, non-excludable, e.g.\ fisheries); private goods (rival, excludable).
\end{keydef}

\emph{Setup.} One public good $y$, one private numeraire $x$. Utility $U^i = u^i(y) + x^i$, $u^i$ strictly concave/increasing. Production cost $c(y)$ in numeraire, increasing/convex/differentiable with $c'(0) = 0$.

\textbf{\textcolor{red}{Planner FOC (Samuelson condition).}}
\[ \boxed{\;\dfrac{du^1(y^*)}{dy} + \dfrac{du^2(y^*)}{dy} = c'(y^*).\;} \tag{4.2} \]
\emph{Sum of marginal benefits = marginal cost} (since the good is non-rivalrous, every agent enjoys every unit produced).

\textbf{\textcolor{red}{CE (private purchase).}} Each agent buys $y^i$ at price $p$; total $\hat y = \hat y^1 + \hat y^2$.
\emph{Consumer FOC:} $u^{i\prime}(\hat y) \leq \hat p$, equality if $\hat y^i > 0$.
\emph{Firm FOC:} $c'(\hat y) = \hat p$.

\textbf{\textcolor{red}{Free-riding $\Rightarrow$ under-provision.}} The agent with smaller marginal valuation sets $\hat y^i = 0$ and free-rides on the other. Combining: $u^{1\prime}(\hat y) = c'(\hat y) \geq u^{2\prime}(\hat y)$ — only \emph{one} marginal valuation drives the level, vs.\ the sum in (4.2). Hence $\hat y < y^*$: public good is under-provided.

\textbf{\textcolor{red}{5.1 --- UNCERTAINTY MODELED: states, contingent commodities, expected utility, risk aversion.}}

\emph{Primitives.} Finite state space $\mathcal{S} = \{1, \ldots, S\}$. \textcolor{orange}{State-contingent commodity} = title to receive a (vector of) physical good(s) iff state $s$ occurs. Portfolio $x^i = (x^i_1, \ldots, x^i_S) \in \mathbb{R}_+^S$ (one physical good per state, for simplicity).

\begin{keydef}
\textbf{Expected utility (von Neumann-Morgenstern).}
\[ U^i(x^i) = \sum_{s=1}^S \pi^i_s\, u^i(x^i_s), \]
where $\pi^i_s$ = agent $i$'s subjective probability of state $s$, $u^i$ = \emph{Bernoulli utility} (state-independent). Additive separability $\Leftrightarrow$ states are mutually exclusive.
\end{keydef}

\textbf{\textcolor{red}{Risk aversion = concave $u$ (Jensen's inequality).}}
$u$ strictly concave $\Leftrightarrow$ $u(\mathbb{E}(x)) > \mathbb{E}(u(x))$ for any non-degenerate $x$.
\emph{Reading.} Agent prefers the certain expected payoff to a lottery with the same mean — the textbook definition of risk aversion.

\textbf{\textcolor{red}{5.2 --- ARROW-DEBREU EQUILIBRIUM: just CE with contingent commodities.}}

\textbf{\textcolor{red}{Two-period timing.}}
$\bullet$ $t = 0$: state unknown. Agents trade ``pieces of paper'' (state-contingent contracts).
$\bullet$ $t = 1$: state $s$ revealed. Contracts are executed (no further trade).

\emph{Single budget at $t=0$:} $\sum_{s} p_s (\omega^i_s - x^i_s) \geq 0$.

\begin{keydef}
\textbf{Definition (AD Equilibrium).} $(\hat p, \hat x) \in \mathbb{R}_+^S \times \mathbb{R}_+^{S \times I}$ such that:
\textbf{(i)} given $\hat p$, each $\hat x^i$ solves $\max U^i(x^i)$ s.t.\ the period-0 budget;
\textbf{(ii)} markets clear: $\sum_i \hat x^i_s = \sum_i \omega^i_s$ for all $s$.
\end{keydef}

\textcolor{orange}{Trick.} Treat ``the same physical good in different states'' as different goods. AD equilibrium = ordinary CE in this enlarged commodity space. So Welfare Theorems apply: AD is PO, every PO can be AD-with-transfers.

\textbf{\textcolor{red}{5.3 --- NO AGGREGATE RISK $+$ common priors $\Rightarrow$ FULL INSURANCE.}}

\emph{Setup.} $I = N = 2$, two states $s = \ell, h$. \textcolor{orange}{No aggregate risk}: $\omega^1_s + \omega^2_s = \omega$ (constant in $s$). \textcolor{orange}{Common priors}: $\pi^i_s = \pi_s$ for all $i$. $u^i$ strictly concave/increasing/differentiable.

\begin{keydef}
\textbf{Proposition (Full insurance).} Under above, PO = AD allocations lie on the \emph{45° line}: $\hat x^i_\ell = \hat x^i_h$ for each $i$.
\emph{Equilibrium prices:} $\hat p_\ell / \hat p_h = \pi_\ell / \pi_h$.
\end{keydef}

\textbf{\textcolor{red}{Proof (sketch, interior, 2 states, 2 agents).}}
PO iff MRS equal across agents: $-\pi_\ell u'(x^1_\ell)/(\pi_h u'(x^1_h)) = -\pi_\ell u'(x^2_\ell)/(\pi_h u'(x^2_h))$. Suppose $x^1_\ell > x^1_h$. Then $u'(x^1_\ell) < u'(x^1_h)$ (strict concavity) and by feasibility $x^2_\ell = \omega - x^1_\ell < \omega - x^1_h = x^2_h$, so $u'(x^2_\ell) > u'(x^2_h)$. The two ratios cannot be equal — contradiction. $\square$

\emph{Reading.} Risk-averse agents pool the risk perfectly when there's no aggregate scarcity and they agree on probabilities.

\textbf{\textcolor{red}{Different priors: lean toward your favored state.}}

If $\pi^1_\ell/\pi^1_h > \pi^2_\ell/\pi^2_h$, then $\hat x^1_\ell > \hat x^1_h$ — agent 1 receives more in the state \emph{he} considers more likely. PO is no longer on 45° line; bets on disagreement become part of the optimal trade.

\textbf{\textcolor{red}{5.5 --- TIME $+$ ASSETS: discounted EU, portfolios, examples.}}

\emph{Time-separable EU with constant Bernoulli:}
\[ U^i(x) = u^i(x_0) + \beta^i \sum_{s=1}^S \pi^i_s\, u^i(x_s), \]
$\beta^i \in (0, 1)$ = subjective discount factor. $s = 0$ \emph{not} mutually exclusive with future states (time $\neq$ risk).

\textbf{\textcolor{red}{Asset $k \in \mathcal{K}$: payoff vector $r^k = (r^k_1, \ldots, r^k_S)$.}}
Portfolio holdings $\theta = (\theta_1, \ldots, \theta_K)$; asset prices $q = (q_1, \ldots, q_K)$.

\emph{Examples.}
$\bullet$ \textbf{Arrow security} $r^s = (0, \ldots, 0, 1, 0, \ldots, 0)$ — pays 1 iff state $s$ realizes.
$\bullet$ \textbf{Risk-free bond} $r^b = (1, 1, \ldots, 1)$ — pays 1 in every state.
$\bullet$ \textbf{European call option} on $r^k$ at strike $c$: payoff $(\max\{0, r^k_s - c\})_{s}$. Example: call on $r^\ell$ at $0.3$ gives $(0.7, 0)$.

\textcolor{orange}{Derivative pricing} is built from these primitives.

\textbf{\textcolor{red}{5.6 --- RADNER SEQUENTIAL EQUILIBRIUM: trade assets at $t{=}0$, spot at $t{=}1$.}}

\textbf{\textcolor{red}{Timing.}}
$\bullet$ $t=0$: consume $x_0$, trade assets $\theta$.
$\bullet$ $t=1$: state $s$ revealed, assets pay $\sum_k r^k_s \theta^i_k$, spot good market opens. Agents consume $x^i_s$.

\textbf{\textcolor{red}{Key requirement: rational expectations.}} Agents anticipate the spot prices that will clear $t=1$ markets — and these expectations are correct.

\emph{Agent $i$'s problem:}
\[ \max_{\theta^i, x^i} U^i(x^i) \quad \text{s.t.} \]
\[ p_0 x^i_0 + \textstyle\sum_k q_k \theta^i_k \;\leq\; p_0 \omega^i_0,\qquad p_s x^i_s \;\leq\; p_s \omega^i_s + \sum_k r^k_s \theta^i_k\;\;\forall s > 0. \]

\begin{keydef}
\textbf{Definition (Radner Equilibrium).} $(\hat q, \hat p, \hat\theta, \hat x)$ such that:
\textbf{(i)} given $(\hat q, \hat p)$, each $(\hat\theta^i, \hat x^i)$ solves agent $i$'s problem;
\textbf{(ii)} good markets clear in every $s$;
\textbf{(iii)} \textcolor{orange}{asset markets clear}: $\sum_i \hat\theta^i_k = 0$ for all $k$ (assets are claims, net zero supply by construction).
\end{keydef}

\textbf{\textcolor{red}{5.7 --- ASSET PRICING via the Stochastic Discount Factor (SDF).}}

\emph{Setup.} Two states, three assets ($r^b$, $r^\ell$, $r^h$ = bond + Arrows), one physical good. Common $u, \beta, \pi$. Interior solution.

\textbf{\textcolor{red}{FOCs of Lagrangian.}}
\[ q_s = \dfrac{p_0}{p_s}\, \dfrac{\pi^i_s\, \beta\, u'(x^i_s)}{u'(x^i_0)}, \qquad q_b = \sum_{s} q_s. \]

\emph{Normalize spot price ratios $p_0/p_s = 1$ (single-good ``real'' assets):}
\[ q_s = \pi_s\, \mu^i_s, \quad q_b = \mathbb{E}[\mu^i], \quad \text{where}\;\; \mu^i_s := \dfrac{\beta\, u'(x^i_s)}{u'(x^i_0)}. \]

\emph{Reading of $\mu^i_s$.} Period-1, state-$s$ marginal utility of wealth \emph{relative to} period-0 marginal utility — ex-post (no $\pi$).

\textbf{\textcolor{red}{Master pricing formula.}}
\[ \boxed{\;q_k = \sum_{s} \pi_s\, \mu^i_s\, r^k_s = \mathbb{E}[\mu^i\, r^k].\;} \]

\begin{keydef}
\textbf{Definition (SDF).} A vector $\mu = (\mu_1, \ldots, \mu_S)$ is a \textit{Stochastic Discount Factor} if every asset is priced linearly: $q_k = \mathbb{E}[\mu\, r^k]$ for all $k$.
\end{keydef}

\textcolor{orange}{Bond price $q_b = \mathbb{E}[\mu]$.} Risk-free rate $R_f := 1/q_b = 1/\mathbb{E}[\mu]$.

\textbf{\textcolor{red}{5.8 --- COMPLETE MARKETS $\Rightarrow$ AD = Radner (and unique SDF).}}

\begin{keydef}
\textbf{Definition (Complete markets).} With $K \geq S$ assets and return matrix $R = [r^1, \ldots, r^K]$: markets are \emph{complete} iff $\mathrm{rank}(R) = S$. Equivalently, $S$ Arrow securities can be replicated by portfolios.
\end{keydef}

\emph{2-state, 2-asset example.} $r^1 = (a, b),\, r^2 = (c, d)$, $\Delta = ad - bc \neq 0$:
$(1, 0) = (d/\Delta) r^1 - (b/\Delta) r^2$, $(0, 1) = -(c/\Delta) r^1 + (a/\Delta) r^2$.

\begin{keydef}
\textbf{Proposition (Unique SDF under complete markets).} If $u$ is increasing, concave, differentiable, and markets are complete, the SDF \emph{exists and is unique}:
\[ \mu_s = \dfrac{q_s}{\pi_s} \quad \forall s, \]
where $q_s$ = Arrow-security equilibrium price. Holds for all agents (Law of One Price).
\end{keydef}

\textbf{\textcolor{red}{AD $\Leftrightarrow$ Radner under complete markets.}}

\begin{keydef}
\textbf{Proposition (Equivalence).} With complete real Arrow markets and one physical good, the Radner spot-price normalization is $\hat p^R_s / \hat p^R_0 = 1$, and:
\textbf{(1)} If $(\hat x^{AD}, \hat p^{AD})$ is AD with $\hat p^{AD} > 0$, then $\hat q^R_s = \hat p^{AD}_s / \hat p^{AD}_0$, $\hat x^R = \hat x^{AD}$ gives a Radner.
\textbf{(2)} Conversely, every Radner equilibrium with $\hat q^R > 0$ yields an AD with $\hat p^{AD}_s = \hat q^R_s$, $\hat x^{AD} = \hat x^R$.
\end{keydef}

\emph{Proof outline.} \textbf{Step 1 (budget equivalence)}: choose $\theta^i_s = x^i_s - \omega^i_s$. \textbf{Step 2 (market clearing)}: asset market clearing reduces to AD goods clearing. So 1st/2nd Welfare Theorems extend to Radner with complete markets.

\textbf{\textcolor{red}{Lucas tree (exogenous-price special case).}} Identical agents (same $\omega$, $u$, $\beta$, $\pi$) $\Rightarrow$ autarchy is the CE, so $\hat x^i_s = \omega_s$ and $\mu_s = \beta u'(\omega_s)/u'(\omega_0)$. Prices become functions of aggregate endowment shocks alone — the workhorse of macro-finance.

\textbf{\textcolor{red}{5.9 --- NO-ARBITRAGE, RISK-RETURN TRADEOFF, CAPM, risk-neutral pricing.}}

\begin{keydef}
\textbf{Definition (No arbitrage).} $(R, q)$ is arbitrage-free if there is no portfolio $\theta \in \mathbb{R}^K$ with $q \cdot \theta \leq 0$ \emph{and} $R\theta \geq 0$ with $R\theta \neq 0$. (No free lunch.)
\end{keydef}

\textbf{\textcolor{red}{Two-way bridge: NA $\Leftrightarrow$ existence of nonneg SDF.}}

\begin{keydef}
\textbf{Prop A.} SDF $\mu > 0$ exists $\Rightarrow$ NA.
\textbf{Prop B (Fundamental Thm of Asset Pricing).} NA $\Rightarrow$ exists SDF $\mu \geq 0$ (via separation theorem). Under complete markets, $\mu > 0$.
\end{keydef}

\begin{proof}[Proof of A]
$q \cdot \theta = \sum_s \pi_s \mu_s (\sum_k r^k_s \theta^k) > 0$ whenever $R\theta \geq 0$ with at least one strict (and $\mu > 0$, $\pi > 0$). So no portfolio with $q\cdot\theta \leq 0$ and $R\theta \geq 0,\neq 0$ exists. $\square$
\end{proof}

\textbf{\textcolor{red}{Risk-return tradeoff (decompose covariance).}}
\[ q_k = \mathbb{E}[\mu r^k] = \mathbb{E}[\mu]\,\mathbb{E}[r^k] + \mathrm{Cov}(\mu, r^k). \]
Divide by $q_k$ and let $\tilde R_k := r^k/q_k$:
\[ \boxed{\;\mathbb{E}[\tilde R_k] = R_f - R_f\,\mathrm{Cov}(\mu,\, \tilde R_k).\;} \]
\emph{Reading.} $\mu$ is decreasing in aggregate consumption (concavity). Assets that pay in \emph{bad} states (positive cov with $\mu$) command \textcolor{orange}{lower} expected returns (insurance). Assets that pay in \emph{good} states (negative cov with $\mu$) command a \textcolor{orange}{risk premium}.

\textbf{\textcolor{red}{CAPM.}}
\[ \mathbb{E}[\tilde R_k] - R_f = \beta_k\, (\mathbb{E}[\tilde R_M] - R_f), \quad \beta_k = \dfrac{\mathrm{Cov}(\tilde R_k, \tilde R_M)}{\mathrm{Var}(\tilde R_M)}. \]
Expected excess return $\propto$ covariance with the market portfolio.

\textbf{\textcolor{red}{Risk-neutral probabilities.}} Define $\hat\pi_s := \pi_s\, \mu_s / \mathbb{E}[\mu]$. Then $\hat\pi$ is a probability measure ($\sum_s \hat\pi_s = 1$, $\hat\pi_s > 0$ when $\mu > 0$), and
\[ \boxed{\;q_k = \dfrac{1}{R_f}\, \hat{\mathbb{E}}[r^k].\;} \]
\emph{Price = expected payoff under $\hat\pi$, discounted at risk-free rate.} This is the workhorse of derivative pricing (Black-Scholes uses this in continuous time).

\textbf{\textcolor{red}{6.2 --- IC, SINGLE-CROSSING, MONOTONICITY.}}

\emph{IC constraints.} $\theta_i q_i - t_i \geq \theta_i q_{-i} - t_{-i}$ \;($IC_1$ and $IC_2$).

\textbf{\textcolor{red}{Single-crossing (Spence-Mirrlees).}} Indifference curves of types $\theta_1, \theta_2$ cross at most once. In quasilinear case: $(\theta_2 - \theta_1) q$ is increasing in $q$, so for any quality difference the sophisticated agent values the increase more.

\begin{keydef}
\textbf{Lemma (Necessity / Monotonicity).} $IC_1 + IC_2 \Rightarrow q_2 \geq q_1$.
\end{keydef}
\begin{proof}
Add LHS and RHS: $\theta_2 q_2 + \theta_1 q_1 \geq \theta_2 q_1 + \theta_1 q_2 \Rightarrow (\theta_2 - \theta_1)(q_2 - q_1) \geq 0$. $\square$
\end{proof}

\begin{keydef}
\textbf{Lemma (Sufficiency).} If $q_2 \geq q_1$, the transfers $t_2 - t_1 = \theta_2(q_2 - q_1)$ make both $IC_1, IC_2$ hold.
\end{keydef}
\begin{proof}
$IC_2$ holds with equality by construction. For $IC_1$: $t_2 - t_1 = \theta_2(q_2 - q_1) \geq \theta_1(q_2 - q_1)$, so $\theta_1 q_1 - t_1 \geq \theta_1 q_2 - t_2$. $\square$
\end{proof}

\textbf{\textcolor{red}{Lemma (Discrimination is optimal).}} Cannot have pooling at the optimum unless serving only one type.

\emph{Sketch.} If both types get $(t, q)$, only $IR_1$ binds. Adding contract $(t^* + k\epsilon, q^* + \epsilon)$ with $\theta_1 \approx C'(q^* + \epsilon) \leq k \leq \theta_2$: $\theta_2$ switches, $\theta_1$ stays. Profits with $\theta_2$ rise (since $k\epsilon > C(q^*+\epsilon) - C(q^*)$ by convexity).

\textbf{\textcolor{red}{7.1 --- MORAL HAZARD: setup + FIRST BEST = full insurance.}}

\emph{Setup (2 actions, 2 outcomes).} Agent action $a \in \{0, 1\}$ (shirk / work). Outcomes: success $x_S$, failure $x_F$ ($x_S > x_F$). Probability of success: $P$ if $a=1$, $p$ if $a=0$ with $P > p$.
Agent: $U = u(w) - a$, $u$ strict.\ concave (risk-averse), $u(0) < \underline U$. Principal (risk-neutral): $\Pi = x - w$.

\textbf{\textcolor{red}{First Best ($a$ observable) — full insurance.}}

\emph{To implement $a=1$:} $\max P(x_S - w_S) + (1-P)(x_F - w_F)$ s.t.\ $Pu(w_S) + (1-P)u(w_F) - 1 \geq \underline U$ (IR).

\begin{keydef}
\textbf{Claim (Full insurance).} At FB, $w_S^\star = w_F^\star$.
\end{keydef}
\begin{proof}
If not, set $\tilde w = Pw_S + (1-P)w_F$. By Jensen: $u(\tilde w) > Pu(w_S) + (1-P)u(w_F) \geq \underline U + 1$. So $\tilde w$ delivers same expected wage with IR slack — can reduce both wages by $\epsilon$ uniformly, raising profits. $\square$
\end{proof}

\emph{FB wage:} $w^\star_1 = u^{-1}(\underline U + 1)$ (for $a=1$); $w^\star_0 = u^{-1}(\underline U)$ (for $a=0$).

\textbf{\textcolor{red}{Implement $a=1$ iff:}}
\[ \boxed{\;(P-p)(x_S - x_F) \;\geq\; u^{-1}(\underline U + 1) - u^{-1}(\underline U).\;} \]
\emph{Reading.} \textcolor{orange}{LHS} = expected output gain from effort; \textcolor{orange}{RHS} = wage premium needed to compensate effort. Effort worth implementing when the gain $\geq$ cost.

\textbf{\textcolor{red}{7.2 --- SECOND BEST (2 actions, 2 outcomes): wage dispersion to satisfy IC.}}

\emph{Setup.} Action unobservable $\Rightarrow$ wages depend only on outcome: $w_S, w_F$.

\textbf{\textcolor{red}{Constraints to implement $a = 1$.}}
\[ \text{(IR)}\;\; Pu(w_S) + (1-P)u(w_F) - 1 \geq \underline U, \qquad \text{(IC)}\;\; [P-p][u(w_S) - u(w_F)] \geq 1. \]

\textcolor{orange}{Reading IC.} If $P, p$ are close (outcome poorly signals effort), wage dispersion must be large to incentivize $a=1$.

\begin{keydef}
\textbf{Claim.} At SB: both IR and IC \emph{bind}.
\end{keydef}

\emph{IR binds:} else reduce $w_F$ uniformly (IC relaxed, profits up).
\emph{IC binds (variational argument):} take small $\epsilon > 0$, perturb $u(w'_S) = u(w_S) - (1-P)\epsilon$, $u(w'_F) = u(w_F) + P\epsilon$. Agent's expected utility unchanged ($+P\cdot(-(1-P)\epsilon) + (1-P)\cdot P\epsilon = 0$). Cost change for principal:
\[ \Delta = P(1-P)\epsilon\bigl(\tfrac{1}{u'(w_F)} - \tfrac{1}{u'(w_S)}\bigr) > 0 \]
since $w_S > w_F$ (IC slack) and $u'$ decreasing. So principal can reduce dispersion until IC binds.

\textbf{\textcolor{red}{Solve the 2×2 system (both binding).}}
\[ u(w_S^{SB}) = \underline U + \tfrac{1-p}{P-p}, \qquad u(w_F^{SB}) = \underline U - \tfrac{p}{P-p}. \]
\emph{Wage gap} $u(w_S^{SB}) - u(w_F^{SB}) = \tfrac{1}{P-p}$. Smaller $P - p$ $\Rightarrow$ larger gap needed.

\textbf{\textcolor{red}{Key economic insight.}} Risk-neutral principal would prefer to insure risk-averse agent (FB = full insurance), but cannot under MH because constant wage $\Rightarrow$ no incentive to work. The wage dispersion is the \textcolor{orange}{incentive cost}.

\textbf{\textcolor{red}{7.3 --- FB vs SB comparison: implementing effort under MH (cost decomposition).}}

\emph{Profit of implementing $a$ under MH:} substitute $w^{SB}$ into objective.

\textbf{\textcolor{red}{Implement $a = 1$ at SB iff:}}
\[ \boxed{\;(P-p)(x_S - x_F) \;\geq\; Pw_S^{SB} + (1-P)w_F^{SB} - w_0^{FB}.\;} \]

\emph{Decomposition of $Pw_S^{SB} + (1-P)w_F^{SB} - w_0^{FB}$ (wage premium for effort):}
$\bullet$ \textbf{Effort compensation cost:} the part that exists already at FB ($u^{-1}(\underline U + 1) - u^{-1}(\underline U)$). Agent needs to be paid for the effort.
$\bullet$ \textbf{Incentive cost (only at SB):} extra wage paid to bear the dispersion. This is the cost of \emph{not insuring} the risk-averse agent fully — Jensen converts wage dispersion into higher expected wage at fixed expected utility.

\textbf{\textcolor{red}{When is effort worth implementing under MH?}}
$\bullet$ $x_S - x_F$ large (output gain from success big).
$\bullet$ $P - p$ not too small (signal informative, low incentive cost via $1/(P-p)$).
$\bullet$ Wage premium small (low effort cost + low risk aversion of the agent).

\textcolor{orange}{Pareto frontier picture.} SB frontier lies inside FB frontier in regions where $a=1$ is implemented. Gap = incentive cost from non-insurance.

\textbf{\textcolor{red}{7.7 --- INSURANCE under moral hazard (monopolist): second best.}}

\emph{Setup.} Agent wealth $\omega$, damage $d < \omega$ with probability $1 - \pi(e)$. Effort $e \in \{0, 1\}$, $\pi(1) > \pi(0)$. Cost $v(1) = v > 0 = v(0)$. Define $c_n = \omega - t_n$ (no-accident consumption), $c_a = \omega - d + t_a$ (accident consumption).

\textbf{\textcolor{red}{SB problem (implement $e = 1$).}}
\[ \max_{c_a, c_n} \pi(1)(\omega - c_n) + (1-\pi(1))(\omega - d - c_a) \]
\[ \text{s.t.}\;\; [\pi(1) - \pi(0)][u(c_n) - u(c_a)] \geq v \;\,(IC), \quad \pi(1) u(c_n) + (1-\pi(1)) u(c_a) - v \geq \underline U(\omega) \;\,(IR). \]

\textbf{\textcolor{red}{Both IC and IR bind (Kuhn-Tucker argument).}}
If $\mu = 0$ on IC, FOCs give $u'(c_n) = u'(c_a) = 1/\lambda$ $\Rightarrow$ $c_n = c_a$ $\Rightarrow$ full insurance $\Rightarrow$ violates IC for $e=1$. Contradiction. So $\mu > 0$.

\textbf{\textcolor{red}{Solution (system of 2 equations).}}
\[ \boxed{\;u(c_a^{SB}) = \underline U(\omega) - \dfrac{\pi(0)}{\pi(1) - \pi(0)} v, \quad u(c_n^{SB}) = \underline U(\omega) + \dfrac{1 - \pi(0)}{\pi(1) - \pi(0)} v.\;} \]

\emph{Reading.} Same logic as 7.2: high-effort state ($c_n$) rewarded, low-effort state ($c_a$) penalized. The wedge $u(c_n) - u(c_a) = v/(\pi(1) - \pi(0))$ is the incentive cost — \textcolor{orange}{partial insurance against the damage, by design}.

\emph{When is $e=1$ optimal?} Compare SB profits for $e=1$ vs.\ FB full-insurance for $e=0$. Standard cost-benefit.

\textbf{\textcolor{red}{8.2 --- FULL GAME: timing + Perfect Bayesian Equilibrium definition.}}

\textbf{\textcolor{red}{Timing (dynamic game).}}
$t = 0$: worker learns $\theta$.
$t = 1$: worker chooses $e$.
$t = 2$: firms (Bertrand) offer wages.
$t = 3$: worker accepts one offer (or none).
$t = 4$: output produced.

\begin{keydef}
\textbf{Perfect Bayesian Equilibrium (PBE).} A quartet $(e^*, w^*, f^*, \mu^*)$ where
$e^*: \Theta \to E$ (education), $w^*_i: E \to W$ (firm's wage), $f^*: \Theta \times E \times W^2 \to \{0,1,2\}$ (worker's accept), $\mu^*: E \to [0,1]$ ($\mu^*(e) = $ Pr($\theta_h \mid e$)).
\end{keydef}

\emph{PBE conditions.}
\textbf{1. Worker rationality (IC + IR):}
\[ w^*(e^*(\theta)) - v(e^*(\theta), \theta) \geq w^*(e) - v(e, \theta) \;\;\forall e, \qquad w^*(e^*(\theta)) - v(e^*(\theta), \theta) \geq 0. \]
\textbf{2. Bertrand wage:} $w^*(e) = \mu^*(e)\theta_h + (1-\mu^*(e))\theta_\ell = \mathbb{E}_{\mu^*}[\theta \mid e]$.
\textbf{3. Beliefs consistency:} On-path beliefs by \textcolor{orange}{Bayes rule}; off-path beliefs $\mu^*(e)$ are \emph{arbitrary} (refinements deal with this).

\emph{Single-crossing reading.} Indifference curves $w = U + v(e, \theta)$ are flatter for high type (lower marginal cost of $e$). The two curves cross at most once.

\textbf{\textcolor{red}{8.3 --- PERFECT INFORMATION BENCHMARK: no signaling needed, $e^* = 0$.}}

\emph{Setup.} Firms observe $\theta$ directly. Wage strategy: $w_i: E \times \Theta \to W$. Subgame Perfect Equilibrium (SPE).

\textbf{\textcolor{red}{Backward induction.}}
\emph{Stage 3+ (worker accepts max wage):} $f^*(\theta, e, w_1, w_2) = \arg\max\{w_1, w_2\}$ (firm 1 if tie).
\emph{Stage 2 (Bertrand):}

\begin{keydef}
\textbf{Claim.} Symmetric Nash: $w_1^*(e, \theta) = w_2^*(e, \theta) = \theta$ (firms make zero profits).
\end{keydef}

\emph{Argument.} $w > \theta$ $\Rightarrow$ negative profits (dominated by $w = \theta$). $w < \theta$ $\Rightarrow$ rival deviates to $w' = (w+\theta)/2$, attracts worker, positive profits. Only $w = \theta$ survives.

\emph{Stage 1 (worker chooses $e$):} since $w$ doesn't depend on $e$ under full info, and education has positive cost, $e^*(\theta) = 0$ for all $\theta$.

\textbf{\textcolor{red}{Full-info SPE.}}
\[ e^*(\theta) = 0, \quad w^*_i(e, \theta) = \theta, \quad f^* = 1. \]
\emph{Both firms make zero profit; no signaling.} This is the FB benchmark.

\textbf{\textcolor{red}{8.4 --- PBE 1: PESSIMISTIC POOLING ($e = 0$, always exists).}}

\begin{keydef}
\textbf{Claim.} For any parameter values, there's a PBE with $e^*(\theta_h) = e^*(\theta_\ell) = 0$.
\end{keydef}

\textbf{\textcolor{red}{Construction.}}
\emph{On-path beliefs (Bayes):} $\mu^*(0) = \nu$ $\Rightarrow$ $w^*(0) = \mathbb{E}_\nu[\theta]$.
\emph{Off-path belief (free):} set $\mu^*(1) = 0$ (most pessimistic interpretation of education) $\Rightarrow$ $w^*(1) = \theta_\ell$.

\emph{Check IR + IC for both types.}
$\bullet$ IR: $w^*(0) = \mathbb{E}_\nu[\theta] \geq \theta_\ell \geq 0 = U$ outside option $\Rightarrow$ both types want to participate.
$\bullet$ IC: $w^*(0) = \mathbb{E}_\nu[\theta] \geq \theta_\ell > w^*(1) - 1/\theta$ for any $\theta$ (since $1/\theta > 0$).

\textbf{\textcolor{red}{Why it always works.}} The pessimistic off-path belief makes $e=1$ unattractive ($w$ drops to $\theta_\ell$ \emph{and} you pay the cost). Neither type wants to deviate.

\emph{Multiplicity.} Many similar pooling-at-0 equilibria exist by varying $\mu^*(1) \in [0, \bar\mu]$ for some $\bar\mu$ that keeps the deviation unattractive.

\textbf{\textcolor{red}{8.5 --- PBE 2: ``RAT-RACE'' POOLING ($e = 1$); condition + Pareto inefficiency.}}

\begin{keydef}
\textbf{Claim.} Rat-race pooling $e^*(\theta_h) = e^*(\theta_\ell) = 1$ is a PBE iff
\[ \mathbb{E}_\nu[\theta] - \tfrac{1}{\theta_\ell} \geq \theta_\ell. \]
\end{keydef}

\textbf{\textcolor{red}{Construction.}}
On-path: $\mu^*(1) = \nu$, $w^*(1) = \mathbb{E}_\nu[\theta]$.
Off-path (free): $\mu^*(0) = 0$, $w^*(0) = \theta_\ell$.

\emph{IC for low type:} $\mathbb{E}_\nu[\theta] - 1/\theta_\ell \geq \theta_\ell$ (the assumption). High type automatically satisfied since $1/\theta_h < 1/\theta_\ell$.

\emph{Reading.} Both types ``rationally'' get education even though education is pure signaling — because off-path beliefs treat $e=0$ as a sign of being low type, and the pessimistic wage at $e=0$ ($\theta_\ell$) is worse than $\mathbb{E}_\nu[\theta] - 1/\theta_\ell$.

\textbf{\textcolor{red}{Pareto dominance.}} Rat-race pooling is Pareto-dominated by $e=0$ pooling: \emph{everybody} pays the education cost for no productive gain. Firms zero profits in both. Welfare strictly higher under no-education.

\textcolor{orange}{Real-world echo.} Credentialism: rising required degrees for jobs that didn't change in skill content.

\textbf{\textcolor{red}{8.6 --- PBE 3: SEPARATING ($e^*(\theta_h) = 1, e^*(\theta_\ell) = 0$); double-IC condition.}}

\begin{keydef}
\textbf{Claim.} Separating PBE exists iff
\[ \theta_h - \tfrac{1}{\theta_\ell} \;\leq\; \theta_\ell \;\leq\; \theta_h - \tfrac{1}{\theta_h}. \]
\end{keydef}

\textbf{\textcolor{red}{Beliefs are pinned down (no off-path freedom).}}
$\mu^*(0) = 0,\, \mu^*(1) = 1$ $\Rightarrow$ $w^*(0) = \theta_\ell,\, w^*(1) = \theta_h$.

\textbf{\textcolor{red}{IC conditions.}}
$\bullet$ \textbf{Low type sticks to $e=0$:} $\theta_\ell \geq \theta_h - 1/\theta_\ell$, i.e.\ low type's cost of mimicking exceeds wage gap. \textcolor{orange}{Bottom condition: $\theta_\ell \geq \theta_h - 1/\theta_\ell$.}
$\bullet$ \textbf{High type prefers $e=1$:} $\theta_h - 1/\theta_h \geq \theta_\ell$, i.e.\ wage gap exceeds high type's cost. \textcolor{orange}{Top condition: $\theta_h - 1/\theta_h \geq \theta_\ell$.}

IR satisfied trivially (both wages $> 0$).

\textbf{\textcolor{red}{Reading: signaling works exactly because of single-crossing.}}
The single-crossing property gives a gap: the wage premium $\theta_h - \theta_\ell$ is enough for the high type to bear $1/\theta_h$, but not enough for the low type to bear $1/\theta_\ell$. Sorting via costly signal.

\emph{Sufficient productivity gap.} If $\theta_h$ and $\theta_\ell$ are too close, neither IC can hold. Separation requires \textcolor{orange}{enough heterogeneity}.

\textbf{\textcolor{red}{8.7 --- COMPETITIVE SCREENING (firms commit first): pooling may fail; non-existence possible.}}

\emph{Timing change.} Firms set wage \emph{functions} $w_i(\cdot)$ \emph{before} worker chooses $e$. (Cf.\ signaling: worker moves first.)

\emph{Worker's joint problem given $(w_1^*, w_2^*)$:} $\max_{e, f} w_f^*(e) - 1/\theta$.

\begin{keydef}
\textbf{Claim.} In competitive screening, pessimistic pooling may \emph{not} be a PBE.
\end{keydef}

\textbf{\textcolor{red}{Cream-skimming deviation.}}
Suppose pooling $w^*(0) = \mathbb{E}_\nu[\theta], w^*(1) = \theta_\ell$. If
\[ \theta_h - \tfrac{1}{\theta_h} \;>\; \mathbb{E}_\nu[\theta] \;>\; \theta_h - \tfrac{1}{\theta_\ell}, \]
then a firm can deviate: offer $w(1) = \theta_h - \epsilon$. Only high types accept (low types unwilling: $\theta_h - \epsilon - 1/\theta_\ell < \mathbb{E}_\nu[\theta]$). Deviator earns positive profit on the high-type segment. Original pooling collapses.

\textbf{\textcolor{red}{Non-existence of pure-strategy equilibrium.}}
If in addition $\theta_h - 1/\theta_\ell > \theta_\ell$ (separating IC for low type fails), neither pooling nor separating PBE works. \textcolor{orange}{No pure-strategy equilibrium} in competitive screening — this is a classical Rothschild-Stiglitz-style result.

\emph{Reading.} Competition forces firms to design contracts that attract specific types (screening). If single-crossing doesn't generate a clean separation between IC margins, the game has no equilibrium in pure strategies (only mixed, or with refinements).

\textbf{\textcolor{red}{8.8 --- LEMONS MARKET \& 2008 financial crash (heterogeneous outside option).}}

\emph{Variant.} Different outside options: $U_h > U_\ell = 0$. High type can opt out of the market at positive value.

\begin{keydef}
\textbf{Claim.} If $\theta_h - 1/\theta_h > U_h > \mathbb{E}_\nu[\theta]$: \textcolor{orange}{the only possible PBE is separating}.
\end{keydef}

\emph{Why pooling fails.} $U_h > \mathbb{E}_\nu[\theta]$ $\Rightarrow$ pooling wage at $e=0$ doesn't satisfy IR for high type — he'd rather take outside option. So $\theta_h$ refuses to participate at pooling wage. Pooling at $e=1$ also fails (worse, by cost). Only separating works (and requires $\theta_h - 1/\theta_h > U_h$).

\textbf{\textcolor{red}{LEMONS market (no signaling available).}} Same parameters but \emph{no education}:

Only equilibrium: $e = 0,\, w(0) = \theta_\ell$. High type \emph{exits the market} (outside option $U_h > \theta_\ell$). Only low types stay.

\textcolor{orange}{Akerlof's lemons.} Without a way to signal, asymmetric info drives the high type out. Market unravels to the lowest type. Pareto-dominated by separating (where high type participates).

\textbf{\textcolor{red}{Application: 2008 financial crash.}}

Reinterpret: $\theta$ = asset return; ``high'' = good asset, ``low'' = toxic. Buyers don't know type. $U_h$ = good-asset holder's outside option (keep the asset).

\emph{Setup:} $\mathbb{E}_\nu[\theta] > U_h > \theta_\ell$ (pooling price > good asset's outside option > bad asset).

\emph{Two PBE without signaling:}
$\bullet$ \textbf{Pooling:} $\bar w = \mathbb{E}_\nu[\theta]$, all participate — market functions.
$\bullet$ \textbf{Lemons:} $\underline w = \theta_\ell$, only bad assets traded — market freezes.

\textcolor{orange}{Coordination failure.} Pessimistic beliefs of buyers $\Rightarrow$ low prices $\Rightarrow$ good-asset holders withdraw $\Rightarrow$ pessimistic beliefs confirmed. Self-fulfilling collapse — argued to underlie the 2008 freeze in structured-credit markets. \emph{Policy:} a credible buyer-of-last-resort at $p = U_h + \epsilon$ kills the lemons equilibrium (TARP-style intervention).

\textbf{\textcolor{red}{10.1 --- STATIC INSURANCE: NO insurance possible (IC forces constant transfer).}}

\emph{Setup.} One good (consumption). Endowment shock $\theta_n \in \{\theta_1, \ldots, \theta_N\}$, $\theta_1 < \cdots < \theta_N$, probability $\pi_n$. Transfer $\tau_n$; consumption $c_n = \tau_n + \theta_n$. Planner minimizes expected cost $\sum_n \pi_n \tau_n$ subject to promise-keeping (PK) $\sum_n \pi_n u(c_n) \geq w$ and IC.

\textbf{\textcolor{red}{Claim (No insurance).}} IC $\Rightarrow$ $\tau_n = \bar\tau$ for all $n$.
\begin{proof}
If not, set $\tau^* = \max_n \tau_n$. Then $\exists i$ with $\tau_i < \tau^*$, and agent $i$ would prefer pretending he got the endowment whose transfer is $\tau^*$ — IC fails. $\square$
\end{proof}

\textcolor{orange}{Intuition.} Without any \emph{state-dependent} instrument to verify $\theta$, anyone with a low transfer mimics the bundle with the highest transfer. The planner has nothing to separate agents.

\textbf{\textcolor{red}{Value function $V(w)$ (cost minimization).}}
$\tau(w)$ solves $\sum_n \pi_n u(\tau(w) + \theta_n) = w$.
\[ V(w) = -\tau(w), \quad V'(w) = -\tau'(w) = -\dfrac{1}{\sum_n \pi_n u'(\tau(w) + \theta_n)} = -\dfrac{1}{\mathbb{E}[u'(c)]}. \tag{10.2} \]

$V$ is \textcolor{orange}{concave} (by change of variables $u_n = u(\tau(w) + \theta_n)$: linear PK constraint + concave objective).

\textbf{\textcolor{red}{10.3 --- SECOND BEST: LDIC binds, $\tau_n^1$ decreasing, $w_n$ increasing.}}

\emph{Relaxed problem.} Replace global IC by local downward IC (LDIC); monotonicity check ex-post.
\[ \max \sum_n \pi_n[-\tau_n^1 + qV(w_n)] \]
\[ \text{s.t.}\;\; \sum_n \pi_n[u(\tau_n^1 + \theta_n) + \beta w_n] \geq U_0 \;(IR, \lambda), \;\; \text{LDIC}_n: u(\tau_n^1 + \theta_n) + \beta w_n \geq u(\tau_{n-1}^1 + \theta_n) + \beta w_{n-1}\;(\mu_n). \]

\textbf{\textcolor{red}{Monotonicity (single-crossing in $(\tau, w)$).}}
Indifference curve slope in $(\tau, w)$ space: $-u'(\tau + \theta)/\beta$, \emph{flatter} for higher $\theta$.
LDIC + LUIC $\Rightarrow$ $\tau_n^1$ \emph{decreasing} in $n$, $w_n$ \emph{increasing} in $n$. \textcolor{orange}{Low-$\theta$ (today unlucky) gets larger transfer today, smaller continuation utility; high-$\theta$ (today lucky) gets smaller transfer today, larger continuation.}

\textbf{\textcolor{red}{All LDIC bind at optimum.}}
Otherwise, increase $w_{n-1}$ and decrease $w_n$ keeping agent welfare constant — improves planner via concavity of $V$.

\textbf{\textcolor{red}{FOCs (with $c_n^1 = \tau_n^1 + \theta_n$).}}
\[ \tau_n^1: \pi_n\bigl[-\tfrac{1}{u'(c_n^1)} + \lambda\bigr] = \mu_{n+1}\tfrac{u'(c_n^1 + \theta_{n+1} - \theta_n)}{u'(c_n^1)} - \mu_n, \tag{10.6} \]
\[ w_n: \pi_n\bigl[qV'(w_n) + \beta\lambda\bigr] = \beta(\mu_{n+1} - \mu_n), \]
with $\mu_1 = \mu_{N+1} = 0$.

\textbf{\textcolor{red}{Intuition: trade-off between period-1 insurance and continuation dispersion.}}
Full period-1 insurance ($c_n^1 = \bar c$) requires large dispersion in $w_n$ (only $w$ left to separate types) — bad for concave $V$. Full continuation pooling ($w_n = \bar w$) requires no period-1 transfer dispersion — no period-1 insurance. Optimum mixes both: \textcolor{orange}{partial insurance in $t=1$, partial dispersion in continuation}.

\textbf{\textcolor{red}{10.4 --- POSITIVE CAPITAL TAXATION (Inverse Euler): SB strictly distorts savings.}}

\textbf{\textcolor{red}{The key inequality (Inverse Euler).}} From (10.6), since $u'(c_n^1 + \theta_{n+1} - \theta_n)/u'(c_n^1) < 1$ (lying makes you eat more, lower $u'$) and $\mu_{n+1} \geq 0$:
\[ \boxed{\;q\, u'(c_n^1) \;<\; \beta\, \mathbb{E}[u'(c_n^2(\theta'))].\;} \tag{10.8} \]

\emph{Comparison.} Recall FB / private savings give equality $q u'(c_1) = \beta \mathbb{E}[u'(c_2)]$. Under SB the LHS is strictly smaller — \textcolor{orange}{agents would, if free, want to save more} (since marginal utility of period-2 consumption exceeds the discounted period-1 marginal utility).

\textbf{\textcolor{red}{Implication: tax savings.}}
If agents had unrestricted access to a risk-free bond, they'd raise $c_2$ and lower $c_1$ until equality. The planner doesn't want this — it weakens incentives. \textcolor{orange}{Optimal capital tax is positive.}

\textbf{\textcolor{red}{Two intuitions.}}
\emph{(a) Joint-deviation.} A bond is a ``bad asset for incentives'' — it pays the same in consumption across states, so it raises utility unevenly across the marginal-utility ladder. Agent who lies (mimicking lower type) gets lower $w$, hence values second-period saving more. The bond facilitates lying.
\emph{(b) IC externality.} A small bond perturbation ($\downarrow c_1$ by $q\epsilon$, $\uparrow c_2$ by $\epsilon$) leaves the planner's budget unchanged but tightens IC. Agent doesn't internalize this; planner taxes to correct.

\textcolor{orange}{Cross-reference.} The same logic justifies the Mirrlees income tax: an action that helps the agent (more $y$, more savings) also tightens an IC he doesn't perceive.
